/* 2. Header & Logo - Ensuring z-index doesn't block clicks */
#p-logo {
    position: relative !important;
    display: block !important;
    width: 100% !important;
    height: 100px !important;
    background: var(--vhx-logo-url) no-repeat left center #FAFDF6 !important;
    border-bottom: 1px solid var(--vhx-border);
    z-index: 5;
}
#p-logo a { display: block; width: 100%; height: 100%; background-image: none !important; }

/* 3. The Action Bar */
#p-cactions {
    position: relative !important;
    background-color: var(--vhx-accent-green) !important;
    padding: 5px 0 !important;
    border-bottom: 1px solid var(--vhx-border);
    text-align: center;
    z-index: 10;
}
#p-cactions li { display: inline-block !important; }

/* 4. Layout Fix: Sidebar and Content Area */
#content {
    margin-right: 210px !important; /* Space for sidebar */
    margin-left: 0 !important;
    border: none !important;
    padding: 20px !important;
    position: relative !important;
    z-index: 1; /* Content stays low */
}

/* Moving sidebar to the right and ensuring it doesn't overlap content */
#mw-panel, #column-one {
    position: absolute !important;
    top: 140px; /* Adjust based on logo + cactions height */
    right: 0 !important;
    left: auto !important;
    width: 180px !important;
    background-color: var(--vhx-sidebar-bg) !important;
    padding: 15px !important;
    border-left: 1px solid #CCC;
    height: auto !important;
    min-height: 400px;
    z-index: 2; /* Sidebar sits above content but only on the right */
}

/* 5. Sidebar Boxes Styling */
.portlet, .mw-portlet {
    background: var(--vhx-white) !important;
    border: 1px solid var(--vhx-border) !important;
    margin-bottom: 15px !important;
    pointer-events: auto !important; /* Force clickability */
}
.portlet h3, .mw-portlet h3 {
    background: var(--vhx-title-bg) repeat-x !important;
    color: #000 !important;
    font-size: 11px !important;
    font-weight: bold !important;
    height: 25px !important;
    line-height: 25px !important;
    padding-left: 10px !important;
    border-bottom: 1px solid var(--vhx-border);
}

/* 6. Clean Up Hide Elements */
#mw-head-base, #mw-page-base, #left-navigation { display: none !important; }

/**
 * Vivahx Retro Theme - Vector Skin Compatibility Fix
 */

/* 1. Global Setup */
:root {
    --vhx-bg: #FDF5C6;
    --vhx-white: #FFFFFF;
    --vhx-sidebar-bg: #F2F2F2;
    --vhx-accent-green: #9ADA92;
    --vhx-border: #999999;
    --vhx-width: 808px;
    --vhx-logo-url: url("https://web.archive.org/web/20060825120444im_/http://www.vivahx.com/images/logo.jpg");
    --vhx-title-bg: url("https://web.archive.org/web/20060825120444im_/http://www.vivahx.com/images/fond_titre.jpg");
}

body {
    background-color: var(--vhx-bg) !important;
    font-family: Verdana, Tahoma, sans-serif !important;
    display: flex;
    justify-content: center;
}

/* 2. Main Wrapper Box[cite: 1] */
#mw-content-container, 
#content, 
#mw-page-base, 
#mw-head-base {
    background: none !important;
}

#content {
    margin: 0 !important;
    border: none !important;
    padding: 25px !important;
}

/* Force the 808px Container[cite: 1] */
#container, #mw-wrapper, .mw-body {
    width: var(--vhx-width) !important;
    max-width: var(--vhx-width) !important;
    margin: 30px auto !important;
    background-color: var(--vhx-white) !important;
    border: 1px solid var(--vhx-border) !important;
    display: grid;
    grid-template-columns: 1fr 200px; /* Content left, Sidebar right */
    grid-template-areas: 
        "header header"
        "toolbar toolbar"
        "main sidebar";
}

/* 3. Header Area */
#p-logo {
    grid-area: header;
    position: relative !important;
    display: block !important;
    width: 100% !important;
    height: 100px !important;
    background: var(--vhx-logo-url) no-repeat left center #FAFDF6 !important;
    border-bottom: 1px solid var(--vhx-border);
    margin: 0 !important;
}
#p-logo a { background-image: none !important; width: 100%; height: 100%; }

/* 4. Top Wiki Toolbar (Action Bar)[cite: 7] */
#p-cactions, #left-navigation, #right-navigation {
    grid-area: toolbar;
    background-color: var(--vhx-accent-green) !important;
    padding: 5px 0 !important;
    border-bottom: 1px solid var(--vhx-border);
    display: flex !important;
    justify-content: center;
    position: static !important;
}

/* 5. Main Content Area[cite: 1] */
#content {
    grid-area: main;
    z-index: 1;
}

/* 6. Sidebar (Right Dock)[cite: 1, 7] */
#mw-panel {
    grid-area: sidebar;
    position: static !important; /* Disables the float that blocks clicks */
    width: 100% !important;
    background-color: var(--vhx-sidebar-bg) !important;
    border-left: 1px solid #CCC;
    padding: 15px !important;
    box-sizing: border-box;
}

/* Sidebar Box Styling[cite: 1] */
.portal, .mw-portlet {
    background: var(--vhx-white) !important;
    border: 1px solid var(--vhx-border) !important;
    margin-bottom: 15px !important;
}

.portal h3, .mw-portlet h3 {
    background: var(--vhx-title-bg) repeat-x !important;
    color: #000 !important;
    font-size: 11px !important;
    font-weight: bold !important;
    height: 25px !important;
    line-height: 25px !important;
    padding-left: 10px !important;
    border-bottom: 1px solid var(--vhx-border);
}

/* Clean up Vector specific tabs/bars */
#mw-head, #mw-panel-base { display: none !important; }
#p-search { margin-top: 10px; }

/**
 * Vivahx Retro Theme - Final Vector Layout Fix
 */

:root {
    --vhx-bg: #FDF5C6;
    --vhx-white: #FFFFFF;
    --vhx-sidebar-bg: #F2F2F2;
    --vhx-accent-green: #9ADA92;
    --vhx-border: #999999;
    --vhx-width: 808px;
    --vhx-logo-url: url("https://web.archive.org/web/20060825120444im_/http://www.vivahx.com/images/logo.jpg");
    --vhx-title-bg: url("https://web.archive.org/web/20060825120444im_/http://www.vivahx.com/images/fond_titre.jpg");
}

/* 1. Global Setup */
body {
    background-color: var(--vhx-bg) !important;
    font-family: Verdana, Tahoma, sans-serif !important;
    font-size: 12px !important;
}

/* 2. The Main Box */
#content, #mw-content-block, #footer {
    width: var(--vhx-width) !important;
    margin: 0 auto !important;
    box-sizing: border-box !important;
}

/* 3. Header and Logo[cite: 1, 7] */
#p-logo {
    position: relative !important;
    width: var(--vhx-width) !important;
    height: 100px !important;
    margin: 30px auto 0 auto !important;
    background: var(--vhx-logo-url) no-repeat left center #FAFDF6 !important;
    border: 1px solid var(--vhx-border);
    border-bottom: none;
    z-index: 100;
}
#p-logo a { display: block; width: 100%; height: 100%; background-image: none !important; }

/* 4. The Green Navigation Bar[cite: 1, 7] */
#mw-head {
    position: relative !important;
    width: var(--vhx-width) !important;
    height: auto !important;
    margin: 0 auto !important;
    background-color: var(--vhx-accent-green) !important;
    border: 1px solid var(--vhx-border);
    border-top: none;
    z-index: 99;
}

/* Styling tabs to look like the 2006 toolbar */
.vectorTabs, #p-cactions {
    background: none !important;
    display: flex !important;
    justify-content: center !important;
}
.vectorTabs li { background: none !important; border: none !important; }
.vectorTabs li a { 
    color: #333366 !important; 
    font-weight: bold !important; 
    padding: 10px 15px !important;
}

/* 5. Content Layout (Flex to prevent overlap) */
#mw-wrapper, .mw-body {
    width: var(--vhx-width) !important;
    margin: 0 auto !important;
    background: var(--vhx-white) !important;
    border: 1px solid var(--vhx-border);
    display: flex !important;
    flex-direction: row !important;
}

#content {
    flex: 1 !important;
    margin: 0 !important;
    border: none !important;
    padding: 25px !important;
    order: 1 !important;
}

/* 6. Sidebar Styled as the "Dock"[cite: 1, 7] */
#mw-panel {
    position: static !important; /* This stops the overlap */
    width: 200px !important;
    background-color: var(--vhx-sidebar-bg) !important;
    border-left: 1px solid #CCC;
    padding: 15px !important;
    order: 2 !important; /* Moves sidebar to the right */
}

/* Sidebar Box Styling[cite: 1] */
.portal, .mw-portlet {
    background: var(--vhx-white) !important;
    border: 1px solid var(--vhx-border) !important;
    margin-bottom: 15px !important;
    width: 170px !important;
}
.portal h3, .mw-portlet h3 {
    background: var(--vhx-title-bg) repeat-x !important;
    color: #000 !important;
    font-size: 11px !important;
    font-weight: bold !important;
    height: 25px !important;
    line-height: 25px !important;
    padding-left: 10px !important;
    border-bottom: 1px solid var(--vhx-border);
    text-transform: none !important;
}

/* 7. Retro Cleanup[cite: 1] */
#mw-page-base, #mw-head-base, #mw-panel-base, .mw-jump-link { display: none !important; }
h1.firstHeading { color: #333366; border-bottom: 1px solid var(--vhx-accent-green); }

/* Sidebar arrow bullet points[cite: 7] */
#mw-panel li { list-style: none !important; margin: 0 !important; padding: 2px 0 !important; }
#mw-panel li a::before { content: "» "; font-weight: bold; }

/* All CSS here will be loaded for users of the MonoBook skin */
/*
 * MAC OS PLATINUM THEME (for MonoBook skin)
 * Replaces the "Classic 95" theme.
 * This theme uses no external files, HTML4-compatible CSS, and web-safe fonts.
 */

/* General Body Styling - "Platinum" Gray */
body {
    font-family: Arial, Helvetica, sans-serif;
    background-color: #EEEEEE; /* Platinum gray */
    color: #000000;
}

/* Main page container */
#globalWrapper {
    background-color: #EEEEEE;
    border: none;
}

/* The white content area */
#content {
    background-color: #FFFFFF;
    color: #000000;
    padding: 10px;
    border: 1px solid #999999; /* Subtle 1px border */
    margin: 10px 0 0 155px; /* Adjust margin to fit sidebar */
}

/* Main page title (e.g., "Hotline Connect Client") */
#firstHeading {
    font-family: Arial, Helvetica, sans-serif;
    font-weight: bold;
    color: #000000;
    border-bottom: 1px solid #CCCCCC;
}

/* All side panels */
#p-personal,
#p-navigation,
#p-search,
#p-tb,
#p-lang {
    margin: 5px;
    background-color: #EEEEEE;
    border: 1px solid #999999; /* Subtle 1px border */
    padding: 0;
}

/* Headers for side panels (e.g., "Navigation", "Search") */
#p-personal h5,
#p-navigation h5,
#p-search h5,
#p-tb h5,
#p-lang h5 {
    font-family: Arial, Helvetica, sans-serif;
    font-weight: bold;
    font-size: 11px;
    background-color: #CCCCCC; /* Mac-style header bar */
    color: #000000;
    padding: 4px 5px;
    margin: 0;
    border: none;
    border-bottom: 1px solid #999999;
}

/* Content area of side panels */
.pBody {
    font-size: 11px;
    background-color: #EEEEEE;
    padding: 5px;
    border: none;
}

/* Use default list style (or remove to let default icons show) */
.pBody ul {
    list-style-type: none;
    padding-left: 5px;
    margin-left: 10px;
}
.pBody ul li {
    padding-bottom: 3px;
}

/* Links */
a {
    color: #0000CC; /* Classic Apple-blue link */
    text-decoration: underline;
}
a:visited {
    color: #551A8B; /* Standard visited purple */
}
a:hover {
    color: #CC0000;
}
/* Colorful Highlight: Red links for non-existent pages */
a.new {
    color: #CC0000 !important;
}

/* H1-H6 Headers */
h1, h2, h3, h4, h5, h6 {
    font-family: Arial, Helvetica, sans-serif;
    font-weight: bold;
    color: #000000;
}

/* Search box */
#searchInput {
    font-family: Arial, Helvetica, sans-serif;
    border: 1px solid #888888;
    background-color: #FFFFFF;
    color: #000000;
    font-size: 12px;
}
/* Search button */
input.searchButton {
    font-family: Arial, Helvetica, sans-serif;
    background-color: #DDDDDD;
    border: 1px outset #999999;
    color: #000000;
    font-size: 11px;
    cursor: pointer;
}

/* Tabs at the top (Article, Discussion, Edit, History) */
#p-cactions ul li a {
    background-color: #CCCCCC;
    border: 1px solid #999999;
    border-bottom: none;
    color: #000000;
    font-weight: normal;
}
#p-cactions ul li a:hover {
    background-color: #DDDDDD;
}
/* Selected tab (connects to white content page) */
#p-cactions ul li.selected a {
    background-color: #FFFFFF;
    border: 1px solid #999999;
    border-bottom: 1px solid #FFFFFF;
    color: #000000;
}

/* Footer */
#footer {
    background-color: #EEEEEE;
    color: #333333;
    font-size: 10px;
    border-top: 1px solid #999999;
}

/* Infoboxes and Tables */
table.infobox,
table.wikitable {
    font-family: Arial, Helvetica, sans-serif;
    border: 1px solid #999999;
    background-color: #FFFFFF;
    color: #000000;
    font-size: 12px;
}
table.infobox th,
table.wikitable th {
    background-color: #EFEFEF;
    border: 1px solid #AAAAAA;
    color: #000000;
}
table.infobox td,
table.wikitable td {
    border: 1px solid #AAAAAA;
}

